// Only transform if the carousel content is present and hasn't been transformed yet
if (element.dataset.textified === '1') return;

// Gather all image-link items from the carousel
const items = element.querySelectorAll('.iacfmit a.iacf_imglnk');
if (!items || items.length === 0) return;

// Build header link (the "Images of Cats" heading href)
const headAnchor = element.querySelector('a.iacf_head');
const headHref = headAnchor ? headAnchor.href : '#';

// Build replacement block
const wrapper = document.createElement('div');
wrapper.style.cssText = 'padding:10px 0 8px 0; border-bottom: 1px solid #e0e0e0; margin-bottom:6px;';

// Section heading
const heading = document.createElement('div');
heading.style.cssText = 'font-size:15px; font-weight:600; margin-bottom:6px; color:#1a1a1a;';
const headLink = document.createElement('a');
headLink.href = headHref;
headLink.target = '_blank';
headLink.textContent = '🔍 Images of Cats';
headLink.style.cssText = 'color:#1a0dab; text-decoration:none;';
heading.appendChild(headLink);
wrapper.appendChild(heading);

// Link list
const ul = document.createElement('ul');
ul.style.cssText = 'list-style:none; margin:0; padding:0; display:flex; flex-wrap:wrap; gap:4px 0;';

items.forEach(function(a) {
  const label = (a.getAttribute('aria-label') || a.querySelector('.imgInfo') && a.querySelector('.imgInfo').textContent || '').trim();
  if (!label) return;
  const li = document.createElement('li');
  li.style.cssText = 'width:50%; box-sizing:border-box; padding:1px 8px 1px 0;';
  const link = document.createElement('a');
  link.href = a.href;
  link.target = '_blank';
  link.textContent = '› ' + label;
  link.style.cssText = 'color:#1a0dab; font-size:13px; text-decoration:none; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; display:block;';
  li.appendChild(link);
  ul.appendChild(li);
});

wrapper.appendChild(ul);

// See all link
const seeAllAnchor = element.querySelector('a.salink');
if (seeAllAnchor) {
  const seeAll = document.createElement('a');
  seeAll.href = seeAllAnchor.href;
  seeAll.target = '_blank';
  seeAll.textContent = 'See all images →';
  seeAll.style.cssText = 'display:inline-block; margin-top:5px; font-size:12px; color:#70757a; text-decoration:none;';
  wrapper.appendChild(seeAll);
}

// Replace inner content
element.innerHTML = '';
element.style.cssText = 'display:block; padding:4px 0;';
element.appendChild(wrapper);
element.dataset.textified = '1';

